import json
import pandas as pd
import pytz
import os

def to_float(s):
    if pd.isna(s): return float('nan')
    if isinstance(s, (int, float)): return float(s)
    s = str(s).strip()
    if not s: return float('nan')
    if '.' in s and ',' in s:
        if s.index('.') < s.index(','):
            s = s.replace('.', '').replace(',', '.')
        else:
            s = s.replace(',', '')
    elif ',' in s:
        s = s.replace(',', '.')
    try:
        return float(s)
    except:
        return float('nan')

def process_all_farms():
    with open("/app/dataset/sensors_calibration.json") as f:
        calib = json.load(f)["enterprise_platform"]["deployment_environments"]["system_config"]["farms"]

    registry = pd.read_csv('/app/dataset/farm_registry.csv')
    farm_ids = registry['farm_id'].tolist()

    farms_info = pd.read_csv('/app/dataset/farms.csv')
    farms_info['farm_name'] = farms_info['farm_name'].str.strip().str.lower()
    registry['farm_name'] = registry['farm_name'].str.strip().str.lower()
    tz_map = pd.merge(registry, farms_info, on='farm_name').set_index('farm_id')['timezone'].to_dict()

    results = {}

    for farm_id in farm_ids:
        file_path = f"/app/dataset/production_{farm_id}.csv"
        if not os.path.exists(file_path):
            results[farm_id] = 0
            continue

        with open(file_path, 'rb') as fp:
            raw = fp.read(4)
        if raw.startswith(b'\xff\xfe') or raw.startswith(b'\xfe\xff'):
            enc = 'utf-16'
        else:
            enc = 'utf-8'

        try:
            with open(file_path, encoding=enc) as fp:
                for _ in range(3): fp.readline()
                header = fp.readline()
            sep = ';' if ';' in header else ','
            df = pd.read_csv(file_path, encoding=enc, skiprows=3, sep=sep, on_bad_lines='skip')
        except Exception as e:
            print(f"Error reading {farm_id}: {e}")
            results[farm_id] = 0
            continue

        df = df.drop_duplicates()

        info = calib.get(farm_id)
        if not info:
            results[farm_id] = 0
            continue

        val_col_name = info['calibration_data']['value_column_name']
        offset = info['calibration_data']['calibration_offset']
        unit = info['sensor_info']['unit'].lower()

        if val_col_name in df.columns:
            val_col = val_col_name
        else:
            val_col = None
            for c in df.columns:
                if c.strip() == val_col_name.strip():
                    val_col = c
                    break
        if not val_col:
            results[farm_id] = 0
            continue

        time_col = None
        for c in df.columns:
            if 'timestamp' in c.lower():
                time_col = c
                break
        if not time_col:
            results[farm_id] = 0
            continue

        # Parse timestamp safely
        # some files have format 14.03.2024, dayfirst=True is needed if pd.to_datetime fails?
        # pd.to_datetime usually handles it if format is consistent
        df['ts_parsed'] = pd.to_datetime(df[time_col], errors='coerce', dayfirst=True)
        df = df.dropna(subset=['ts_parsed'])

        tz = pytz.timezone(tz_map[farm_id].strip())
        df['ts_utc'] = df['ts_parsed'].dt.tz_localize(tz, ambiguous='NaT', nonexistent='NaT').dt.tz_convert('UTC')
        df = df.dropna(subset=['ts_utc'])

        temp_col = None
        for c in df.columns:
            if 'temperature' in c.lower() and 'inverter' in c.lower():
                temp_col = c
                break

        if temp_col:
            df[temp_col] = df[temp_col].apply(to_float)
            spikes = df[df[temp_col] > 85.0]['ts_utc'].tolist()
            def is_valid(ts):
                for s in spikes:
                    if ts > s and ts <= s + pd.Timedelta(minutes=45):
                        return False
                return True
            df = df[df['ts_utc'].apply(is_valid)]

        if farm_id == 'FARM_C':
            start = tz.localize(pd.to_datetime('2024-03-16 08:00:00')).astimezone(pytz.UTC)
            end = tz.localize(pd.to_datetime('2024-03-16 12:00:00')).astimezone(pytz.UTC)
            df = df[~((df['ts_utc'] >= start) & (df['ts_utc'] <= end))]
        elif farm_id == 'FARM_F':
            start = tz.localize(pd.to_datetime('2024-03-15 12:00:00')).astimezone(pytz.UTC)
            end = tz.localize(pd.to_datetime('2024-03-15 14:00:00')).astimezone(pytz.UTC)
            df = df[~((df['ts_utc'] >= start) & (df['ts_utc'] <= end))]

        df = df.sort_values('ts_utc')

        df['val'] = df[val_col].apply(to_float)
        df = df.dropna(subset=['val'])
        df['true_val'] = df['val'] - offset

        df['dt_hours'] = df['ts_utc'].diff().dt.total_seconds() / 3600.0
        df['dt_hours'] = df['dt_hours'].fillna(0)

        df = df[df['true_val'] >= 0]

        day_start = pd.to_datetime('2024-03-15 00:00:00', utc=True)
        day_end = pd.to_datetime('2024-03-16 00:00:00', utc=True)
        df = df[(df['ts_utc'] >= day_start) & (df['ts_utc'] < day_end)]

        if unit in ['kwh']: factor = 1.0; is_power = False
        elif unit in ['mwh']: factor = 1000.0; is_power = False
        elif unit in ['wh']: factor = 0.001; is_power = False
        elif unit in ['btu']: factor = 0.000293071; is_power = False
        elif unit in ['kw']: factor = 1.0; is_power = True
        elif unit in ['mw']: factor = 1000.0; is_power = True
        elif unit in ['w']: factor = 0.001; is_power = True
        else: factor = 1.0; is_power = False

        if is_power:
            energy = (df['true_val'] * df['dt_hours'] * factor).sum()
        else:
            energy = (df['true_val'] * factor).sum()

        results[farm_id] = int(round(energy))
        print(f"{farm_id}: unit={unit}, energy={energy:.2f}")

    return results

print(process_all_farms())
